def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f"Key {key!r} not found")<|return|>

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying storage
    if hasattr(self, "_items"):
        items = self._items
    else:
        # Fallback to items() if available
        items = self.items() if hasattr(self, "items") else None

    # If we couldn't find a suitable container, raise an error
    if items is None:
        raise AttributeError("No internal storage (_items or items) found")

    # Handle dict-like storage
    if isinstance(items, dict):
        if not keys:
            return list(items.values())
        return [items[k] for k in keys]

    # Handle list/tuple-like storage
    if isinstance(items, (list, tuple)):
        if not keys:
            return list(items)
        return [items[k] for k in keys]

    # Fallback: try to iterate over items assuming it's an iterable of values
    if not keys:
        return list(items)
    return [items[k] for k in keys]<|return|>

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no specific keys are requested, return all items
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            name = self._keys[key]
            result[name] = self._values[key]
        else:
            # Treat as a field name
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result<|return|>

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    seen = set()
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        if f in seen:
            raise TypeError(f"Duplicate field name: {f!r}")
        seen.add(f)
    namespace = {'__slots__': fields, 'srid_map': srid_map}
    def __init__(self, *args, **kwargs):
        if len(args) + len(kwargs) != len(fields):
            raise TypeError(f"Expected {len(fields)} arguments")
        for f, val in zip(fields, args):
            setattr(self, f, val)
        for f in fields[len(args):]:
            if f in kwargs:
                setattr(self, f, kwargs.pop(f))
            else:
                raise TypeError(f"Missing value for field {f!r}")
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs)}")
    namespace['__init__'] = __init__
    return type(name, (Point,), namespace)<|return|>

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator<|return|>

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if not isinstance(maxsize, int) or maxsize <= 0:
            raise TypeError('maxsize must be a positive integer')
        cache = OrderedDict()
        lock = threading.RLock()

        def _make_key(args, kwds, typed):
            key = args
            if kwds:
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted(kwds.items()))
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            now = timer()
            with lock:
                if key in cache:
                    value, expire = cache.pop(key)
                    if expire > now:
                        cache[key] = (value, expire)
                        return value
                # compute new value
                value = func(*args, **kwargs)
                expire = now + ttl
                cache[key] = (value, expire)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return value

        return wrapper
    return decorator<|return|>

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        usage = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            if maxsize <= 0:
                return func(*args, **kwargs)

            # Build a hashable key from the arguments
            if typed:
                key = args + tuple(sorted(kwargs.items())) + \
                      tuple(type(arg) for arg in args) + \
                      tuple(type(v) for v in kwargs.values())
            else:
                key = args + tuple(sorted(kwargs.items()))

            if key in cache:
                usage[key] += 1
                return cache[key]

            # Compute the result and store it
            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1

            # Evict least frequently used item if cache is too large
            if len(cache) > maxsize:
                # Find the minimum usage count
                min_count = min(usage.values())
                # Evict the first key with that count
                for k in list(usage):
                    if usage[k] == min_count:
                        del cache[k]
                        del usage[k]
                        break

            return result

        return wrapper

    return decorator<|return|>

