def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    result = {}
    for name in dir(self):
        if name.startswith('_'):
            continue
        attr = getattr(self, name)
        if not all and callable(attr):
            continue
        desc = getattr(attr, '__doc__', '')
        if desc is None:
            desc = ''
        result[name] = desc.strip() if isinstance(desc, str) else ''
    return result<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Try to obtain the error array for the requested coordinate
    err = None
    if hasattr(self, "errors") and coord_name in self.errors:
        err = self.errors[coord_name]
    elif hasattr(self, "Data") and coord_name in self.Data:
        err = self.Data[coord_name].get("err")
    # If no error information is available, return all indices
    if err is None:
        # Determine the length of the coordinate from available attributes
        if hasattr(self, "coords") and coord_name in self.coords:
            length = len(self.coords[coord_name])
        elif hasattr(self, "_variables") and coord_name in self._variables:
            length = len(self._variables[coord_name])
        else:
            length = 0
        return np.arange(length)
    # Convert to a NumPy array for consistency
    err_arr = np.asarray(err)
    # Return indices where the error value is neither NaN nor zero
    return np.where(~np.isnan(err_arr) & (err_arr != 0))[0]<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Reject if seq itself is a Source instance
    if isinstance(seq, Source):
        return False
    # Accept if seq is a FillRequest instance
    if isinstance(seq, FillRequest):
        return True
    # If seq is iterable, look for any FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        pass
    return False<|return|>

