def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    # If level is 0, we do not recurse and do not include differing values
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2}

    result = {}
    for k, v in d1.items():
        if k not in d2:
            # key only in d1
            result[k] = v
        else:
            v2 = d2[k]
            # both values are dicts: recurse if allowed
            if isinstance(v, dict) and isinstance(v2, dict):
                # determine next recursion depth
                next_level = level - 1 if level > 0 else -1
                subdiff = difference(v, v2, next_level)
                if subdiff:
                    result[k] = subdiff
            else:
                # non-dict values: include if they differ and recursion allowed
                if level != 0 and v != v2:
                    result[k] = v
    return result<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    messages = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            if not KEY_REGEX.match(key):
                messages.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    messages.append({repr(v): 'expected string or bytes-like object'})
                else:
                    if not VALUE_REGEX.match(v):
                        messages.append(
                            {v: f"Label value '{v}' does not match the regex [...]"}
                        )
        else:
            if not isinstance(value, (str, bytes)):
                messages.append({repr(value): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(value):
                    messages.append(
                        {value: f"Label value '{value}' does not match the regex [...]"}
                    )

    if messages:
        raise ValidationError(messages)<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application spec has an observers list
    if not hasattr(app.spec, "observers") or app.spec.observers is None:
        app.spec.observers = []

    # Build a set of (kind, name) tuples for resources that already have an observer schema
    existing = set()
    for obs in app.spec.observers:
        if isinstance(obs, dict) and "resource" in obs:
            res = obs["resource"]
            kind = res.get("kind")
            name = res.get("name")
            if kind and name:
                existing.add((kind, name))

    # Iterate over all resources in the manifest
    for res in app.spec.manifest:
        kind = res.get("kind")
        name = res.get("metadata", {}).get("name")
        if not kind or not name:
            continue  # skip malformed resources

        key = (kind, name)
        if key in existing:
            continue  # skip resources that already have a custom observer schema

        # Create a minimal default observer schema for this resource
        default_schema = {
            "resource": {
                "kind": kind,
                "name": name
            },
            "schema": {
                "type": "object",
                "properties": {}
            }
        }
        app.spec.observers.append(default_schema)<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        path = os.path.abspath(path)
    except Exception:
        return False
    if not os.path.isdir(path):
        return False
    # Check for OCFL root marker
    ocfl_root = os.path.join(path, '.ocfl_root')
    pyfs_root = os.path.join(path, '.pyfs_root')
    if os.path.isfile(ocfl_root) or os.path.isfile(pyfs_root):
        return True
    # Fallback: look for typical OCFL structure
    objects_dir = os.path.join(path, 'objects')
    if os.path.isdir(objects_dir):
        return True
    return False<|return|>

