def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    log = getattr(self, 'validation_log', getattr(self, 'log', []))
    if not log:
        return ''
    lines = []
    if isinstance(log, dict):
        for key, value in log.items():
            line = f"{key}: {value}"
            if prefix:
                line = f"{prefix}{line}"
            lines.append(line)
    else:
        for entry in log:
            line = str(entry)
            if prefix:
                line = f"{prefix}{line}"
            lines.append(line)
    return "\n".join(lines)<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ArgumentError("inventory", "Inventory must be a dict, got %s" % type(inventory).__name__)

    # Optionally extract spec version from the 'type' field
    if extract_spec_version:
        type_value = inventory.get('type')
        if isinstance(type_value, str):
            # Example: 'v2', 'inventory_v3', etc.
            if type_value.startswith('v') and type_value[1:].isdigit():
                self.spec_version = int(type_value[1:])
            elif type_value.endswith('_v' + type_value.split('_')[-1]):
                try:
                    self.spec_version = int(type_value.split('_')[-1])
                except ValueError:
                    pass  # keep existing spec_version

    # Validate required fields
    required = getattr(self, 'required_fields', [])
    for field in required:
        if field not in inventory:
            raise ArgumentError(field, "Missing required field '%s'" % field)

    # Validate each field against its spec
    field_specs = getattr(self, 'field_specs', {})
    for key, value in inventory.items():
        spec = field_specs.get(key)
        if spec is None:
            continue  # unknown field, skip or optionally raise
        # Verify the spec itself
        self._verify_type(spec, key)
        # Validate the value against the spec
        self._validate_type(value, key)

    return inventory<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing = []
    for file, digest in manifest_files.items():
        if digest not in digests_used:
            missing.append((file, digest))
    if missing:
        msg = ", ".join(f"{f}:{d}" for f, d in missing)
        raise ValueError(f"Missing digests for files: {msg}")
    return True<|return|>

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Check that the prior version is older than the current one
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise AttributeError("Both InventoryValidator objects must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(f"Prior version ({prior.version}) must be older than current version ({self.version})")

    # Helper to compare collections
    def _check_subset(name, prior_set, current_set):
        if not set(prior_set).issubset(set(current_set)):
            missing = set(prior_set) - set(current_set)
            raise ValueError(f"Prior {name} {missing} not present in current inventory")

    # Inventory items (keys) must be a subset
    if hasattr(prior, "inventory") and hasattr(self, "inventory"):
        _check_subset("inventory keys", prior.inventory.keys(), self.inventory.keys())
    else:
        raise AttributeError("Both InventoryValidator objects must have an 'inventory' attribute")

    # Species must be a subset
    if hasattr(prior, "species") and hasattr(self, "species"):
        _check_subset("species", prior.species, self.species)
    else:
        raise AttributeError("Both InventoryValidator objects must have a 'species' attribute")

    # Parameters must be a subset
    if hasattr(prior, "parameters") and hasattr(self, "parameters"):
        _check_subset("parameters", prior.parameters, self.parameters)
    else:
        raise AttributeError("Both InventoryValidator objects must have a 'parameters' attribute")

    # Constraints must be a subset
    if hasattr(prior, "constraints") and hasattr(self, "constraints"):
        _check_subset("constraints", prior.constraints.keys(), self.constraints.keys())
    else:
        raise AttributeError("Both InventoryValidator objects must have a 'constraints' attribute")

    # If all checks pass, return True
    return True<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    for logical_path, ver_map in inventory.items():
        files = set()
        # Support two common inventory formats:
        # 1. dict of version -> content_file
        # 2. list of (version, content_file) tuples
        if isinstance(ver_map, dict):
            items = ver_map.items()
        elif isinstance(ver_map, (list, tuple)):
            items = ver_map
        else:
            # Unknown format, skip
            continue

        for ver, content in items:
            try:
                # Try to compare versions as strings; if they look like numbers, compare numerically
                if isinstance(ver, str) and isinstance(version, str):
                    # Simple numeric comparison if possible
                    def _to_tuple(v):
                        return tuple(int(part) if part.isdigit() else part for part in v.replace('-', '.').split('.'))
                    if _to_tuple(ver) >= _to_tuple(version):
                        files.add(content)
                else:
                    if ver >= version:
                        files.add(content)
            except Exception:
                # Fallback: include if string comparison works
                if str(ver) >= str(version):
                    files.add(content)
        if files:
            result[logical_path] = files
    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dict")
        if 'path' not in entry:
            raise ValueError("File entry missing 'path'")
        path = entry['path']
        if path not in manifest_files:
            raise ValueError(f"File '{path}' in fixity block not present in manifest")
    return True<|return|>

