def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ''

    # Convert pieces to a list of strings
    if isinstance(pieces, dict):
        # Order of components for a typical semantic version
        order = ['major', 'minor', 'patch', 'build', 'prerelease']
        parts = [str(pieces[k]) for k in order if k in pieces and pieces[k] is not None]
    else:
        parts = [str(p) for p in pieces if p is not None]

    if style == 'full':
        return '.'.join(parts)
    elif style == 'short':
        return parts[0] if parts else ''
    elif style == 'semantic':
        major = parts[0] if len(parts) > 0 else ''
        minor = parts[1] if len(parts) > 1 else ''
        patch = parts[2] if len(parts) > 2 else ''
        return f"v{major}.{minor}.{patch}"
    elif style == 'build':
        if isinstance(pieces, dict):
            return str(pieces.get('build', ''))
        return parts[-1] if parts else ''
    else:
        raise ValueError(f"Unknown style: {style}")<|return|>

