def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Assume the storage root provides an iterable of objects to validate.
    storage_root = getattr(self, "_storage_root", None)
    if storage_root is None:
        return num_objects, good_objects

    # If the storage root has a method to retrieve objects, use it; otherwise iterate directly.
    objects = storage_root.get_objects() if hasattr(storage_root, "get_objects") else storage_root

    for obj in objects:
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # The object is expected to expose a validate() method.
                obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Validation failed for {obj!r}: {exc}")

        if check_digests and is_valid:
            try:
                # The object is expected to expose a check_digest() method that returns a bool.
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"[WARNING] Digest mismatch for {obj!r}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Digest check error for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

