def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            continue
        for k, v in d.items():
            if k in result:
                try:
                    result[k] += v
                except TypeError:
                    # If values are not numeric, store as list of values
                    if isinstance(result[k], list):
                        result[k].append(v)
                    else:
                        result[k] = [result[k], v]
            else:
                result[k] = v
    return result<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    Args:
        url (str): The URL containing placeholders in the form {name}.
        url_args (Mapping[str, Any]): A mapping of placeholder names to
            replacement values.

    Returns:
        str: The URL with placeholders replaced by the corresponding values.
    """
    if not url:
        return ''

    if not url_args:
        return url

    # Find placeholders of the form {name}
    pattern = re.compile(r'\{([^}]+)\}')

    def _repl(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))

    return pattern.sub(_repl, url)<|return|>

