def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        for sub in c.__subclasses__():
            if sub not in seen:
                queue.add(sub)

    seen.discard(cls)
    return seen<|return|>

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove matching leading and trailing single or double quotes
    match = re.match(r"^(['\"])(.*)\1$", name)
    if match:
        return match.group(2)
    return name<|return|>

