def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    if host.lower() == 'localhost':
        return True
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == '::1':
                return True
    return False<|return|>

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a compiled regex pattern.
    If the input is already a compiled pattern, it is returned unchanged.
    If the input is a string, it is optionally stripped of leading/trailing
    whitespace before compilation.
    """
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Assume any object with a 'pattern' attribute is a compiled regex
    if hasattr(pattern, 'pattern'):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")<|return|>

