def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # 1. Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate {candidate!r} does not provide interface {iface!r}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for {candidate!r} against {iface!r}: {exc}"
            )

    # 2. Check that all required methods are present
    try:
        method_names = iface.getMethodNames()
    except AttributeError:
        # Fallback for older zope.interface versions
        method_names = [name for name in iface.names() if isinstance(getattr(iface, name), type(iface))]

    for name in method_names:
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}' in {candidate!r}")
            continue
        # Check signature compatibility
        try:
            candidate_sig = inspect.signature(getattr(candidate, name))
            iface_sig = inspect.signature(getattr(iface, name))
            # Compare parameter lists (names and kinds)
            cand_params = list(candidate_sig.parameters.values())
            iface_params = list(iface_sig.parameters.values())
            if len(cand_params) != len(iface_params):
                errors.append(
                    f"Signature mismatch for method '{name}': "
                    f"expected {len(iface_params)} params, got {len(cand_params)}"
                )
            else:
                for cp, ip in zip(cand_params, iface_params):
                    if cp.kind != ip.kind or cp.name != ip.name:
                        errors.append(
                            f"Signature mismatch for method '{name}': "
                            f"parameter '{cp.name}' kind {cp.kind} does not match interface "
                            f"parameter '{ip.name}' kind {ip.kind}"
                        )
                        break
        except Exception as exc:
            errors.append(
                f"Error inspecting signature for method '{name}' in {candidate!r}: {exc}"
            )

    # 3. Check that all required attributes are present
    try:
        attr_names = iface.getAttributeNames()
    except AttributeError:
        # Fallback for older zope.interface versions
        attr_names = [name for name in iface.names() if not isinstance(getattr(iface, name), type(iface))]

    for name in attr_names:
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}' in {candidate!r}")

    # 4. Raise collected errors or return True
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))
    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        return True

    # If candidate is a class, check subclass relationship
    if isinstance(candidate, type):
        if issubclass(candidate, iface):
            return True
    else:
        # candidate is an instance
        if isinstance(candidate, iface):
            return True

    # Fallback: check that candidate implements all callable attributes of iface
    import inspect
    iface_methods = [name for name, obj in inspect.getmembers(iface, predicate=inspect.isfunction)]
    for name in iface_methods:
        if not hasattr(candidate, name):
            raise TypeError(
                f"Candidate {candidate!r} does not implement method {name!r} required by {iface.__name__}"
            )
        attr = getattr(candidate, name)
        if not callable(attr):
            raise TypeError(
                f"Attribute {name!r} of candidate {candidate!r} is not callable as required by {iface.__name__}"
            )
    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise TypeError("No bases provided")

    # Gather the metaclasses of all bases
    metas = [type(b) for b in bases]

    # Find the most derived common metaclass
    common_meta = metas[0]
    for m in metas[1:]:
        if issubclass(common_meta, m):
            # common_meta is already a subclass of m, keep it
            pass
        elif issubclass(m, common_meta):
            # m is more derived, use it
            common_meta = m
        else:
            # Find a common ancestor in the MROs
            common = None
            for anc in common_meta.__mro__:
                if anc in m.__mro__:
                    common = anc
                    break
            if common is None:
                raise TypeError(
                    "metaclass conflict: no common metaclass found for bases"
                )
            common_meta = common

    # If an explicit metaclass was supplied, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a type")
        if not issubclass(explicit_mc, common_meta):
            raise TypeError(
                "metaclass conflict: the metaclass of a derived class must be a "
                "subclass of the metaclasses of all its bases"
            )
        return explicit_mc

    return common_meta<|return|>

