def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Add attributes to existing <a> tags
    def add_attrs(tag):
        if 'target=' not in tag:
            tag = tag.replace('<a ', '<a target="_blank" ', 1)
        if 'rel=' not in tag:
            tag = tag.replace('<a ', '<a rel="noopener" ', 1)
        return tag

    # Process existing <a> tags
    result = []
    pos = 0
    while True:
        start = text.find('<a ', pos)
        if start == -1:
            result.append(text[pos:])
            break
        end = text.find('</a>', start)
        if end == -1:
            result.append(text[pos:])
            break
        end += len('</a>')
        result.append(add_attrs(text[start:end]))
        pos = end

    processed = ''.join(result)

    # Linkify plain URLs
    def linkify(s):
        out = []
        i = 0
        while i < len(s):
            if s.startswith('http://', i) or s.startswith('https://', i):
                j = i
                while j < len(s) and s[j] not in ' \t\n\r':
                    j += 1
                url = s[i:j]
                # strip trailing punctuation
                trailing = ''
                while url and url[-1] in '.,;!?)':
                    trailing = url[-1] + trailing
                    url = url[:-1]
                out.append(f'<a href="{url}" target="_blank" rel="noopener">{url}</a>{trailing}')
                i = j
            else:
                out.append(s[i])
                i += 1
        return ''.join(out)

    return linkify(processed)<|return|>

