def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the XML document
    try:
        root = etree.fromstring(doc)
    except Exception:
        return False

    # Find the Signature element (namespace-aware)
    ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
    sig_node = root.find('.//ds:Signature', namespaces=ns)
    if sig_node is None:
        return False

    # Verify the signature using the provided public key
    try:
        ctx = xmlsec.SignatureContext()
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        ctx.key = key
        return ctx.verify(sig_node)
    except Exception:
        return False<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        data = json.loads(document)
        result = {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "links": []
        }
        for link in data.get("links", []):
            result["links"].append({
                "rel": link.get("rel"),
                "href": link.get("href"),
                "type": link.get("type"),
                "template": link.get("template")
            })
        return result
    except Exception:
        # Fallback to XRD (XML)
        try:
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_el = root.find("xrd:Subject", ns)
            result = {
                "subject": subject_el.text if subject_el is not None else None,
                "aliases": [a.text for a in root.findall("xrd:Alias", ns)],
                "links": []
            }
            for link_el in root.findall("xrd:Link", ns):
                result["links"].append({
                    "rel": link_el.get("rel"),
                    "href": link_el.get("href"),
                    "type": link_el.get("type"),
                    "template": link_el.get("template")
                })
            return result
        except Exception:
            return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split("@")[1]
    except (IndexError, AttributeError):
        return None
    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        with urllib.request.urlopen(url) as resp:
            return resp.read().decode("utf-8")
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    import fnmatch
    patterns = spec_option if isinstance(spec_option, (list, tuple)) else [spec_option]
    files = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if any(fnmatch.fnmatch(fname, pat) for pat in patterns):
                    files.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(files)<|return|>

