@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping")
    required = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [f for f in required if f not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data<|return|>

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}") from e
    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file {yaml_file} does not contain a mapping at the top level")
    required_fields = ['name', 'version', 'data']
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in {yaml_file}: {', '.join(missing)}")
    return data<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # 1. Try to get a value from the spec first
        spec_val = None
        try:
            spec_val = self.spec.get(arg.name)
        except AttributeError:
            # If spec is not a dict-like object, ignore
            pass

        if spec_val is not None:
            defaults[arg.name] = spec_val
        else:
            # 2. Fallback to the option's own default if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # 3. If the option is a dictionary option, recurse into its scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults

    return defaults<|return|>

