def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements.
    # This should be defined on the instance, e.g. self.deprecated_args = {'old': 'new'}
    deprecated_map = getattr(self, 'deprecated_args', {})

    # Helper to process a single argument dictionary.
    def _process_args(source_name, args):
        if not isinstance(args, dict):
            return
        for key in list(args.keys()):
            if key in deprecated_map:
                new_key = deprecated_map[key]
                # Emit a warning about the deprecation.
                try:
                    import warnings
                    warnings.warn(
                        f"Argument '{key}' from {source_name} is deprecated; "
                        f"use '{new_key}' instead.",
                        DeprecationWarning,
                        stacklevel=2,
                    )
                except Exception:
                    # Fallback to printing if warnings module is unavailable.
                    print(
                        f"WARNING: Argument '{key}' from {source_name} is deprecated; "
                        f"use '{new_key}' instead."
                    )
                # Move the value to the new key if it doesn't already exist.
                if new_key not in args:
                    args[new_key] = args.pop(key)
                else:
                    # If both old and new keys are present, prefer the new one.
                    args.pop(key)

    _process_args('CLI', cli_args)
    _process_args('Answer file', answer_file_args)<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Get option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        # If condition is callable, evaluate it with args
        if callable(cond):
            try:
                if cond(args):
                    required.append(name)
            except Exception:
                # If the condition raises, ignore it
                continue
        else:
            # If condition is a truthy value, treat it as satisfied
            if cond:
                required.append(name)

    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        arg_def = arg_defs.get(arg_name, {})
        max_len = arg_def.get('max_length') or arg_def.get('length')
        if max_len is None:
            continue
        if value is None:
            continue
        try:
            val_len = len(value)
        except TypeError:
            continue
        if val_len > max_len:
            abort(f"Argument '{arg_name}' length {val_len} exceeds maximum {max_len}")<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        # Skip if the argument is not defined in the spec
        if arg_name not in arg_defs:
            continue
        arg_def = arg_defs[arg_name]
        # If the argument has a 'choices' key, validate the value
        if 'choices' in arg_def:
            choices = arg_def['choices']
            # Allow the value to be a list of choices if the spec expects a list
            if isinstance(arg_value, (list, tuple)):
                invalid = [v for v in arg_value if v not in choices]
                if invalid:
                    msg = (
                        f"Invalid choice(s) for argument '{arg_name}': "
                        f"{invalid}. Allowed choices: {choices}"
                    )
                    abort(msg)
            else:
                if arg_value not in choices:
                    msg = (
                        f"Invalid choice for argument '{arg_name}': "
                        f"'{arg_value}'. Allowed choices: {choices}"
                    )
                    abort(msg)<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Import argparse only when needed to avoid global imports
    import argparse
    import re

    def complex_type(value):
        """Parse and validate a value according to spec_option."""
        # Cast to the specified type if provided
        if 'type' in spec_option:
            try:
                value = spec_option['type'](value)
            except Exception as exc:
                raise argparse.ArgumentTypeError(
                    f"Invalid value for {option_name}: {exc}"
                )

        # Enforce allowed choices if specified
        if 'choices' in spec_option:
            if value not in spec_option['choices']:
                raise argparse.ArgumentTypeError(
                    f"{option_name} must be one of {spec_option['choices']}"
                )

        # Enforce a regular expression pattern if provided
        if 'regex' in spec_option:
            pattern = spec_option['regex']
            if not re.match(pattern, str(value)):
                raise argparse.ArgumentTypeError(
                    f"{option_name} does not match pattern {pattern}"
                )

        # Custom validation function
        if 'validator' in spec_option:
            validator = spec_option['validator']
            if not validator(value):
                raise argparse.ArgumentTypeError(
                    f"{option_name} failed custom validation"
                )

        return value

    # Give the function a descriptive name and docstring
    complex_type.__name__ = f"{subcommand}_{type_name}_{option_name}_type"
    complex_type.__doc__ = (
        f"Complex type for option '{option_name}' in subcommand '{subcommand}'. "
        f"Spec: {spec_option}"
    )
    return complex_type<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars (each item should be a dict)
        :return: The updated dictionary
        """
        if vars_dict is None:
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict, got %r" % type(vars_dict).__name__)

        if not extra_vars:
            return vars_dict

        # If a single dict is provided, treat it as a list of one
        if isinstance(extra_vars, dict):
            extra_vars = [extra_vars]
        elif not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or dict, got %r" % type(extra_vars).__name__)

        for item in extra_vars:
            if not isinstance(item, dict):
                raise TypeError("Each item in extra_vars must be a dict, got %r" % type(item).__name__)
            vars_dict.update(item)

        return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # If a schema is defined for this parser, use it to cast values
    schema = getattr(self, 'parser_schemas', {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        # Use explicit type from schema if available
        if key in schema:
            expected_type = schema[key]
            try:
                values_dict[key] = expected_type(val)
                continue
            except Exception:
                # fall back to generic inference if conversion fails
                pass
        # Generic inference for string values
        if isinstance(val, str):
            lowered = val.lower()
            if lowered in ("true", "false"):
                values_dict[key] = lowered == "true"
            else:
                try:
                    if "." in val:
                        values_dict[key] = float(val)
                    else:
                        values_dict[key] = int(val)
                except ValueError:
                    # keep original string if it cannot be converted
                    pass
    # No return needed; values_dict is modified in place.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Determine the spec file (JSON or YAML)
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_path):
        spec_path = os.path.join(plugin_dir, 'plugin.yaml')
        if not os.path.exists(spec_path):
            raise FileNotFoundError(f"No plugin spec found in {plugin_dir}")

    # Load the spec
    with open(spec_path, 'r', encoding='utf-8') as f:
        if spec_path.endswith('.json'):
            spec = json.load(f)
        else:
            if yaml is None:
                raise RuntimeError("PyYAML is required to load YAML plugin spec")
            spec = yaml.safe_load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)<|return|>

